dict.string:
.navbar {
	font-family: Arial, sans-serif;
	font-size: 1em;
	color: #666;
	margin: 9px 0px 6px 0px;
	line-height: 30px;
}

.navbar-bg {
	text-align: center;
}

.navbar-bg ul {
	list-style: none;
	margin: 0px;
	padding: 0px;
}


li {
	list-style-type: none;
	display: inline;
	padding: 0px 10px 0px 10px;
}


li a {
	text-decoration: none;
	color: #666;
}

li a:visited {
	text-decoration: none;
	color: #666;
}

li a:hover{
 	color: #463C3C;
	text-decoration: none;}


li.current-page a{	 color: #463C3C;
	text-decoration: none;
	font-weight: bold;}
